{"content":"def to_markdown(rows, columns=None):
    """Render a list of dicts as a Markdown table."""
    if columns is None:
        columns = []
        for r in rows:
            for k in r.keys():
                if k not in columns:
                    columns.append(k)
    else:
        columns = list(columns)

    if not rows and not columns:
        return ""

    # Prepare rows and cells
    processed_rows = []
    for r in rows:
        row_cells = []
        for c in columns:
            val = r.get(c)
            if val is None:
                cell_str = ""
            else:
                cell_str = str(val)
                cell_str = cell_str.replace("\r\n", " ").replace("\n", " ").replace("\r", " ")
                cell_str = cell_str.replace("|", r"\|")
            row_cells.append(cell_str)
        processed_rows.append(row_cells)

    # Process header cells
    header_cells = []
    for c in columns:
        h_str = str(c)
        h_str = h_str.replace("\r\n", " ").replace("\n", " ").replace("\r", " ")
        h_str = h_str.replace("|", r"\|")
        header_cells.append(h_str)

    # Column width = the largest of 3, the header length, and the length of every cell (after escaping).
    col_widths = []
    for i, c in enumerate(columns):
        width = max(3, len(header_cells[i]))
        for row_cells in processed_rows:
            width = max(width, len(row_cells[i]))
        col_widths.append(width)

    # A column is numeric if every non-empty value in it is an int or float (bool does not count as numeric).
    is_numeric = []
    for i, c in enumerate(columns):
        numeric = True
        has_non_empty = False
        for r in rows:
            raw_val = r.get(c) if r is not None else None
            if raw_val is None or raw_val == "":
                continue
            has_non_empty = True
            if isinstance(raw_val, bool) or not isinstance(raw_val, (int, float)):
                numeric = False
                break
        if not has_non_empty:
            numeric = False
        is_numeric.append(numeric)

    def format_cell(cell_str, width, numeric):
        if numeric:
            return cell_str.rjust(width)
        else:
            return cell_str.ljust(width)

    formatted_header = [format_cell(h, col_widths[i], is_numeric[i]) for i, h in enumerate(header_cells)]
    header_line = "| " + " | ".join(formatted_header) + " |"

    sep_cells = []
    for i, w in enumerate(col_widths):
        dashes = "-" * w
        if is_numeric[i]:
            dashes = dashes[:-1] + ":"
        sep_cells.append(dashes)
    sep_line = "| " + " | ".join(sep_cells) + " |"

    body_lines = []
    for row_cells in processed_rows:
        formatted_row = [format_cell(row_cells[i], col_widths[i], is_numeric[i]) for i in range(len(columns))]
        body_lines.append("| " + " | ".join(formatted_row) + " |")

    all_lines = [header_line, sep_line] + body_lines
    return "\n".join(all_lines)
